import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.CDA9RsCr.js";const p=JSON.parse('{"title":"Features","description":"","frontmatter":{},"headers":[],"relativePath":"en/intro/features.md","filePath":"en/intro/features.md","lastUpdated":1794581028000}'),i={name:"en/intro/features.md"};function n(s,e,l,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><h2 id="real-time-danmaku-draw" tabindex="-1">Real-time danmaku draw <a class="header-anchor" href="#real-time-danmaku-draw" aria-label="Permalink to &quot;Real-time danmaku draw&quot;">​</a></h2><p>Once connected to a room the app listens to danmaku continuously. Any message containing your keyword is added to the draw pool — no manual list-keeping for the streamer or mods. A viewer sending several qualifying messages in the same room is counted once, keeping the draw fair.</p><p>An empty keyword means &quot;collect everything&quot;: every viewer who speaks joins the pool, and the lottery page labels the active mode. At draw time the configured number of winners is picked at random and written to the active profile&#39;s history.</p><h2 id="watch-and-draw-on-one-screen" tabindex="-1">Watch and draw on one screen <a class="header-anchor" href="#watch-and-draw-on-one-screen" aria-label="Permalink to &quot;Watch and draw on one screen&quot;">​</a></h2><p>The lottery page puts the stream, the room list and the danmaku feed together:</p><ul><li><strong>Stream player</strong> — an embedded HLS player following the selected room; the cover shows while the room is offline.</li><li><strong>Room list</strong> — every joined room with its streamer, online count and live status; click to switch the preview.</li><li><strong>Live danmaku</strong> — the current room&#39;s feed, including Bilibili&#39;s built-in emotes such as <code>[oh]</code>.</li></ul><p>The feed sticks to the bottom by default. Scrolling up pauses auto-follow, and about three seconds after you stop it snaps back. Incoming lines are batched so a busy room cannot re-render per message.</p><h2 id="stability-during-long-streams" tabindex="-1">Stability during long streams <a class="header-anchor" href="#stability-during-long-streams" aria-label="Permalink to &quot;Stability during long streams&quot;">​</a></h2><ul><li><strong>Player watchdog</strong> — some streams stall silently: no <code>error</code> or <code>stalled</code> event fires and <code>currentTime</code> stops advancing. The player checks the clock every 1.5s; after 5s without progress it attempts a soft resume, and if that fails it rebuilds the player with a fresh play URL, backing off up to 20s.</li><li><strong>Danmaku reconnect</strong> — the danmaku WebSocket reconnects with backoff. The handshake carries the login state and <code>buvid3</code>, so nicknames are not masked and UIDs are not zeroed (which would collapse every viewer into one participant).</li></ul><h2 id="two-login-methods" tabindex="-1">Two login methods <a class="header-anchor" href="#two-login-methods" aria-label="Permalink to &quot;Two login methods&quot;">​</a></h2><ul><li><strong>Cookie login</strong> — copy the Bilibili Cookie from a browser and paste it in.</li><li><strong>QR-code login</strong> — click &quot;QR login&quot; to generate a code and scan it with the Bilibili mobile app. Expired and scanned states are surfaced, and the code can be refreshed at any time.</li></ul><h2 id="multiple-draw-profiles" tabindex="-1">Multiple draw profiles <a class="header-anchor" href="#multiple-draw-profiles" aria-label="Permalink to &quot;Multiple draw profiles&quot;">​</a></h2><p>Keep a profile per scenario. Each stores its own keyword, winner count, joined rooms and background image. Switching a profile switches all of it at once, and every profile survives restarts.</p><h2 id="draw-history-and-export" tabindex="-1">Draw history and export <a class="header-anchor" href="#draw-history-and-export" aria-label="Permalink to &quot;Draw history and export&quot;">​</a></h2><p>Every draw is recorded automatically under the active profile — keyword, winner count, draw time and the full winner list. The &quot;History&quot; tab in Settings lets you:</p><ul><li><strong>Export one</strong> — write the winner list to a Markdown file named <code>keyword-count-time.md</code>, with a nickname + UID table.</li><li><strong>Delete one</strong> — remove a single entry.</li><li><strong>Delete all</strong> — clear every entry for the current profile (with a confirmation dialog).</li></ul><p>Switching profiles switches the list. Deleting a profile clears its history too, and each profile keeps the latest 100 entries.</p><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2><ul><li><strong>Light / dark</strong> — switch manually; the first launch follows the system preference and the choice is remembered.</li><li><strong>Backgrounds</strong> — the default gradient, the spring-festival or beach image, or an image you upload.</li><li><strong>Accent</strong> — sampled from the active background, then expanded into a full primary ramp, so every page follows one palette.</li><li><strong>Language</strong> — built-in 中文 / English switch, Chinese by default.</li></ul><h2 id="interaction-details" tabindex="-1">Interaction details <a class="header-anchor" href="#interaction-details" aria-label="Permalink to &quot;Interaction details&quot;">​</a></h2><ul><li>When results show, the stage keeps its aspect ratio and the winners list fills only the remaining height inside its card, so the page itself never gains a scrollbar.</li><li>Panel and list scrollbars appear only while scrolling and fade out when idle.</li><li>Copying the winner list tries the browser clipboard first, then the native backend clipboard, then a system command over the dev bridge.</li><li>Rooms can be added by ID or by pasting a live-room link.</li></ul>',22)])])}const m=a(i,[["render",n]]);export{p as __pageData,m as default};
